('0c3f73d3-323f-417c-8bc6-69c419cb0849', '5503b08e-ede2-476d-8050-4529ba2d501d', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d147dea232352f', '19d147dea232352f', 'Payment gateway memory leak blocking production deploy', 'replied', '2026-03-22 07:41:30.37944+00', '<CAMgkX2Sr-8eRiXVU7JvvSxL2DgVwT3vN768G_K3qdArixb3V3w@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:15:00.133+00', 'I can assist with this investigation immediately. Please share the heap dump files from the most recent crash and I will analyze the object retention patterns to identify the source.', '2026-03-22 14:04:48.218382+00'),
('7e864579-63c5-4f10-b7e0-138141b97e01', 'b32165de-4fb3-4066-85e2-5ed84698499e', '9d26237a-36b9-4e11-a290-32619c63f07b', '19d1485e4e3605f0', '19d1485e4e3605f0', 'Quick tech check for Thursday''s client call?', 'replied', '2026-03-22 07:50:12.803935+00', '<CAAQV21gJYA1_HdNob6GcqJZQaBYQKS1cYZKCDaS+cwh1e2QZhA@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:11:00.498+00', 'Yeah no problem, I''m free around 2:30 if that works? I''ll bring my headphones just in case.', '2026-03-22 14:04:48.218382+00'),
('f6e2c8f4-4a92-40b8-8858-d1b9e31044d0', '9d26237a-36b9-4e11-a290-32619c63f07b', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d149d04959bc9f', '19d149d04959bc9f', 'Sprint 42 planning - auth module estimates are MIA', 'replied', '2026-03-22 08:15:28.515282+00', '<CAKsyQ_io9-O3AuF3qpwO440OkLZZv_-txjgLbwSDR66PY4PTFQ@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:30:00.026+00', 'Yeah I noticed that too - I''m free at 3pm to pair on it?', '2026-03-22 14:04:48.218382+00'),
('6d9d6e97-ad2d-47aa-9fa1-0639dca220ad', 'ac111555-8a56-4759-aedd-ee45443cb207', '764e7cac-aff3-44c3-91ad-48abf7450602', '19d149a0fcc7e665', '19d149a0fcc7e665', 'Duplicate payment records from webhook race condition (#4451) blocking Thursday deploy', 'replied', '2026-03-22 08:12:14.54551+00', '<CAACUBocpuUXwGCctCFNb0xoEPPAX5qw5Lx+Zt5vv93EeMJatSA@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:37:13.034+00', 'Thank you for bringing this critical issue to my attention. I will review the logs immediately and prioritize the idempotency fix to ensure we deploy safely on Thursday.', '2026-03-22 14:04:48.218382+00'),
('4190fcd9-8d32-409b-af26-ad57e2c22052', 'c293472a-256c-41c1-a1e6-28b5983812a3', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d14a2484b761a1', '19d14a2484b761a1', 'Production rollback required due to Stripe payment failures', 'replied', '2026-03-22 08:21:13.893838+00', '<CACph0-JtF=KQ4dXC+G=bjijc_eeev-in+zbQk2ULcMwrPwBwMA@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:45:00.03+00', 'I have initiated the rollback procedure and will monitor the deployment logs for the next hour. Please confirm once you have verified that transaction processing has returned to normal levels.', '2026-03-22 14:04:48.218382+00'),
('702d3684-3a31-45de-826d-2f116e32d326', 'c293472a-256c-41c1-a1e6-28b5983812a3', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d14b028b94a7dc', '19d14b028b94a7dc', 'Escape room booking for March 15th - Engineering team offsite', 'replied', '2026-03-22 08:36:22.924958+00', '<CACph0-+ZWE=73GDP8=u+vm7teTfWGm-rqHL4-i68CSeJRVp4Ew@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:37:13.034+00', 'Thank you for coordinating this event. I will review the details and confirm my availability by the end of the week.', '2026-03-22 14:04:48.218382+00'),
('14121023-fb51-4e36-b68d-0206a2ba1ed9', '8dda8cab-57a2-468f-b483-9c5663218bf8', 'eec657c2-6704-4494-be4b-68a6801c75ac', '19d2033768c22f30', '19d2033768c22f30', 'Concerning trend in Azure migration delays - FY24 impact assessment', 'sent', '2026-03-24 14:15:37.668241+00', '<CAGrnLouQU9akQMR+8fYvo8RUZ4fyxYqz6zBvkgRiBLDsAyQCsw@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, NULL, 'Thank you for bringing this to my attention. Could you prepare a summary of the affected accounts for discussion during tomorrow''s operations standup?', '2026-03-24 14:15:37.668241+00'),
('de0bf73b-19b9-4994-9180-e24412819ffc', 'ac111555-8a56-4759-aedd-ee45443cb207', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d14b1101922a33', '19d14b1101922a33', 'Stripe API documentation finalized for Thursday deployment', 'replied', '2026-03-22 08:37:22.689387+00', '<CAACUBofdGYcw=E7gqNP=j1SsdROghYi0s7KcnjUywYZHQp8+sQ@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Thank you for delivering this ahead of schedule. I will review the documentation this afternoon and confirm the deployment timeline with the stakeholders.', '2026-03-22 14:04:48.218382+00'),
('ba5113fe-aa98-4d76-a64c-688f830e4ba5', 'b32165de-4fb3-4066-85e2-5ed84698499e', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d14b3f7fc7ae4e', '19d14b3f7fc7ae4e', 'Offer letter question - start date flexibility?', 'replied', '2026-03-22 08:40:32.417917+00', '<CAAQV21h=LGqgWSYZktBwE51eMi1L6cXoZumMraekBr3BDphSZw@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Yeah the 20th works perfectly! Super excited to have you on board.', '2026-03-22 14:04:48.218382+00')
INSERT INTO public.warmup_emails (id, from_account_id, to_account_id, gmail_message_id, thread_id, subject, status, sent_at, rfc_message_id, landed_in_spam, spam_detected_at, spam_rescued_at, marked_important_at, reply_detected_at, reply_scheduled_at, reply_content, created_at) VALUES
('2ff4505b-3e7c-4964-a5f4-51a6220df446', 'b32165de-4fb3-4066-85e2-5ed84698499e', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d1498581edfbf4', '19d1498581edfbf4', 'Fixed the auth service crash - you''re unblocked', 'replied', '2026-03-22 08:10:22.527087+00', '<CAAQV21hmFeE3-nferXKfxE966z7mcGBO=wwJv09dpV5yk2Z1xw@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Sweet, thanks for the quick fix! I can finally stop telling users to clear their cookies.', '2026-03-22 14:04:48.218382+00'),
('83234343-d88f-4e10-aa79-9d28517065c9', '5503b08e-ede2-476d-8050-4529ba2d501d', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d1499bc3db2f33', '19d1499bc3db2f33', 'Saturday deployment window for payment gateway maintenance', 'replied', '2026-03-22 08:11:53.878585+00', '<CAMgkX2TUDV3dn3eXrLAZedrifzAhP=py6RE33Dmw9JGtKk6Ang@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'I will be available on Saturday evening to cover the deployment. Please send over the runbook documentation prior to the weekend.', '2026-03-22 14:04:48.218382+00'),
('5f1935dc-f2e2-4a02-a865-fa17d8c469a4', '764e7cac-aff3-44c3-91ad-48abf7450602', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d14af70d863906', '19d14af70d863906', 'Request for coverage: Saturday database maintenance window', 'replied', '2026-03-22 08:35:35.640288+00', '<CAPDcXfPDoeAaG=c08oSH8bLuDk7a1xytzMMyOdF_BsnYono0=w@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'I can certainly cover the Saturday evening maintenance window. Please forward the runbook and escalation contacts before Thursday evening.', '2026-03-22 14:04:48.218382+00'),
('cd60854c-c9a4-4673-be70-687c571c5b57', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '764e7cac-aff3-44c3-91ad-48abf7450602', '19d14a63a9cd6753', '19d14a63a9cd6753', 'That null check you added in auth.middleware.js', 'replied', '2026-03-22 08:25:32.569996+00', '<CAKc7ywV1mkiCOiL9vw7m7dgub3Y0fTHq3jvE=YoTE67vtrt83Q@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Good point on the logging level - I''ll tweak that and merge. Thanks!', '2026-03-22 14:04:48.218382+00'),
('e5bbff4e-12be-4112-b035-731dc4763666', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d1493b37220592', '19d1493b37220592', 'Did we actually 2x mobile activation yesterday?', 'replied', '2026-03-22 08:05:17.722888+00', '<CAKc7ywXT7F6KY82WWfYB9n-Ri0NUZqttm+=FjAPBAOS5eJ103g@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Nice catch! Yeah let''s jump on a call - I have a feeling it might be related to that tracking fix we pushed on Tuesday.', '2026-03-22 14:04:48.218382+00'),
('1ca9c5da-5c5d-42a1-8fe8-1a1d35ca3a02', '5503b08e-ede2-476d-8050-4529ba2d501d', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d148fd24c669cc', '19d148fd24c669cc', 'Database sharding strategy documentation posted to Backend Team Confluence', 'replied', '2026-03-22 08:01:03.642842+00', '<CAMgkX2TPjnBxQi5P8n78HJo+Hwcm=4HsR5Wd7D=BoxGUmhVTuw@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:15:00.133+00', 'Thank you for publishing this documentation. I will review the sharding strategy this afternoon and send my comments before the end of the week.', '2026-03-22 14:04:48.218382+00'),
('d443e09f-47db-4c0c-90f6-971b647c5c7d', '9d26237a-36b9-4e11-a290-32619c63f07b', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d14b00adec6b87', '19d14b00adec6b87', 'Victory tacos Thursday at Maria''s after crushing the checkout fix?', 'replied', '2026-03-22 08:36:15.394859+00', '<CAKsyQ_i7D7B-nV8HS2FK_7yc+yycOOjye_da-O83BbRfyha_VA@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:30:00.026+00', 'I''m so down for tacos! Thursday works for me and I have opinions about the guacamole - we definitely need extra.', '2026-03-22 14:04:48.218382+00'),
('f579af3f-9b50-4104-995f-69f27526e713', '5503b08e-ede2-476d-8050-4529ba2d501d', '764e7cac-aff3-44c3-91ad-48abf7450602', '19d14b077ba3f1c4', '19d14b077ba3f1c4', 'Building C garage elevator maintenance requires Level 2 relocation', 'replied', '2026-03-22 08:36:43.169626+00', '<CAMgkX2QjAS7__8M9f13XgY6Rv-9aDagqUVDq0mvW5DG5obvxsw@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Thank you for the advance notification. I will relocate my vehicle to Level 4 this afternoon and contact the facilities desk regarding the temporary access card.', '2026-03-22 14:04:48.218382+00'),
('b824d04c-5627-415f-ab72-428acbe1287a', '5503b08e-ede2-476d-8050-4529ba2d501d', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d149d786974072', '19d149d786974072', 'Slack channel for Aurora migration coordination', 'replied', '2026-03-22 08:15:58.355875+00', '<CAMgkX2QN83_RxGCSTGDmNrhRpKRdmTBEwpH=dNz8puSmLNZ8Yg@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:15:00.133+00', 'This is an excellent suggestion. Please proceed with creating the channel and invite the database team immediately.', '2026-03-22 14:04:48.218382+00'),
('01dffe6f-87b6-41c9-bc56-406c49b80cbe', '764e7cac-aff3-44c3-91ad-48abf7450602', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d148f700a0566a', '19d148f700a0566a', 'Alex Chen joins Backend Engineering on March 15th', 'replied', '2026-03-22 08:00:38.742362+00', '<CAPDcXfPYK_A_L3WgjcNCvjPHW=Bk76aL8+RUjP7+fvx2GJ62oQ@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Welcome to the team, Alex. I look forward to collaborating with you on the Kubernetes migration project and please let me know if you require any assistance with your development environment setup.', '2026-03-22 14:04:48.218382+00')
INSERT INTO public.warmup_emails (id, from_account_id, to_account_id, gmail_message_id, thread_id, subject, status, sent_at, rfc_message_id, landed_in_spam, spam_detected_at, spam_rescued_at, marked_important_at, reply_detected_at, reply_scheduled_at, reply_content, created_at) VALUES
