('f897d37f-1118-4e7c-8e51-e0aca7d734a2', 'b32165de-4fb3-4066-85e2-5ed84698499e', '764e7cac-aff3-44c3-91ad-48abf7450602', '19d14a5f08bf3816', '19d14a5f08bf3816', 'Stripe webhook still giving you grief?', 'replied', '2026-03-22 08:25:13.450791+00', '<CAAQV21gB4u+BsqjRvW8Tc+5_dJFYxRzH+gFHfjfZWDb8p_-E6w@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Oh yeah, I had to regenerate the API keys but it''s working now. Thanks for the heads up!', '2026-03-22 14:04:48.218382+00'),
('edc11361-21da-40bc-904b-066090fbc2d3', '3a3d1b34-ffef-4ca1-bef9-592596f22a4a', 'eec657c2-6704-4494-be4b-68a6801c75ac', '19d2037f09a53d74', '19d2037f09a53d74', 'Swagger docs for the payment webhook are finally accurate', 'sent', '2026-03-24 14:20:31.011366+00', '<CAKnbhc+cFrZSVkrr3eLygLcw+F0LGctUYLRgv19pU3+s-=UQqQ@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, NULL, 'Awesome, thanks for catching that! I was literally about to file a bug for it.', '2026-03-24 14:20:31.011366+00'),
('590cc94d-29b1-4681-9993-e6adfe72aa96', '9d26237a-36b9-4e11-a290-32619c63f07b', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d14d41357a493b', '19d14d41357a493b', 'Fixed that weird CSV export bug Sarah found yesterday', 'replied', '2026-03-22 09:15:36.798031+00', '<CAKsyQ_j_isBOW-rj1siqvdYP2gcwLYBx_5ZmQpCn3MrM4_tLrg@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:30:00.026+00', 'Awesome, thanks for the quick fix! I''ll test it out this afternoon and let you know if I spot anything weird.', '2026-03-22 14:04:48.218382+00'),
('7d1bbd00-5bb8-4a67-9dc2-fc1be9183cd2', '9d26237a-36b9-4e11-a290-32619c63f07b', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d14bdabd7cdc12', '19d14bdabd7cdc12', 'Coffee chat about comp before Sarah''s offsite?', 'replied', '2026-03-22 08:51:08.655929+00', '<CAKsyQ_hHtjACo2RjK4TujGCXnsAUuv5+1__u4AqfM7+F=gfWCA@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:37:13.034+00', 'Sounds good! How about Thursday at 3pm in the kitchen?', '2026-03-22 14:04:48.218382+00'),
('7dd18cf1-1e82-4682-82cc-5daaf1950bfa', 'c293472a-256c-41c1-a1e6-28b5983812a3', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d14c7443508466', '19d14c7443508466', 'Wishing you a swift recovery from your shoulder surgery', 'replied', '2026-03-22 09:01:37.674825+00', '<CACph0-+wyGypvp_eMk+CnFcMUks5ShAa7zaHhX6K_ACEMetMkA@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 15:00:00.027+00', 'I deeply appreciate the team''s support and look forward to rejoining you all in a few weeks. Thank you for covering my sprint responsibilities during this time.', '2026-03-22 14:04:48.218382+00'),
('fe39f3ef-48b7-4c6f-b99d-126cc70c2493', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '9d26237a-36b9-4e11-a290-32619c63f07b', '19d14b41d635c0cd', '19d14b41d635c0cd', 'Whiteboarding the notification overhaul Thursday with Dave', 'replied', '2026-03-22 08:40:42.31035+00', '<CAKc7ywWXc35tMm+uo9bhobSfewVgFxPGRKr5XB_TSSH0Jcg+tw@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:15:00.133+00', 'Count me in! I''ll swing by with some donuts to go with that coffee.', '2026-03-22 14:04:48.218382+00'),
('e9256486-4f7a-4656-b159-b3c84b0d9cb6', '764e7cac-aff3-44c3-91ad-48abf7450602', '9d26237a-36b9-4e11-a290-32619c63f07b', '19d14c67bc4fb7c3', '19d14c67bc4fb7c3', 'Phase 2 Redis caching implementation deployed to production', 'replied', '2026-03-22 09:00:45.992224+00', '<CAPDcXfOqx93ChBW_v9Y48fOmr4r=FR1m0Pw916zsXCrq2Fxkng@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:11:00.498+00', 'Thank you for the update. I have reviewed the metrics and will circulate the documentation to the stakeholder group prior to tomorrow''s briefing.', '2026-03-22 14:04:48.218382+00'),
('beaf41c0-4834-43ef-a25a-a5b9266df4dc', 'c293472a-256c-41c1-a1e6-28b5983812a3', 'b32165de-4fb3-4066-85e2-5ed84698499e', '19d14b8b30e0b2d2', '19d14b8b30e0b2d2', 'Flight and hotel booked for Denver leadership summit', 'replied', '2026-03-22 08:45:42.192549+00', '<CACph0-L7NrLtmacAgmgFQQSFDXwgjqtDXeGkd5DzrCzVhD_Q=g@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Thank you for finalizing these arrangements. I have reviewed the documents and everything appears to be in order.', '2026-03-22 14:04:48.218382+00'),
('53220750-9f14-4563-a1f4-aee1f24599f7', '9d26237a-36b9-4e11-a290-32619c63f07b', '4e7037ca-fc19-4c1c-98bd-e41025172b5b', '19d14cf2c759a1cc', '19d14cf2c759a1cc', 'Ctrl+Shift+T just saved me from losing that research tab', 'replied', '2026-03-22 09:10:15.93068+00', '<CAKsyQ_jqLzsn0FGBdYXrx1BY3kuUA9mDsTJkWbD9F1GkpTPymQ@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Oh nice, I always forget about that one! Definitely going to start using it more often.', '2026-03-22 14:04:48.218382+00')
