('7b473954-e80b-4534-8a35-f2de15effd27', 'ac111555-8a56-4759-aedd-ee45443cb207', '764e7cac-aff3-44c3-91ad-48abf7450602', '19d14a2856a9d16a', '19d14a2856a9d16a', 'Sarah Chen promoted to Senior Engineer following Mercury release', 'replied', '2026-03-22 08:21:29.344043+00', '<CAACUBocBBt--uwfLuidnQAXhnhJn4VJhX-ZAHtW3D9RaC66A=Q@mail.gmail.com>', 'f', NULL, NULL, NULL, NULL, '2026-03-22 14:23:39.17+00', 'Please convey my congratulations to Sarah on this thoroughly deserved promotion. Her work on the Mercury release has set a new standard for technical leadership within our team.', '2026-03-22 14:04:48.218382+00'),
